#include <stdio.h>
#include <string.h>

int C[605][605]; // binomial mod 2

int main(){
    // Precompute binomial coefficients mod 2
    for(int i=0;i<605;i++){
        C[i][0]=1;
        for(int j=1;j<=i;j++) C[i][j]=(C[i-1][j-1]+C[i-1][j])%2;
    }
    int N; scanf("%d",&N);
    int a[N],b[N];
    for(int i=0;i<N;i++) scanf("%d%d",&a[i],&b[i]);
    // For each k, invariant = sum C(a[i], k-b[i]) mod 2 = C(X, k-Y)
    // Try all possible X, Y in reasonable range
    // Coordinates seem bounded; let's find range
    int inv[605]={0};
    for(int k=0;k<605;k++){
        for(int i=0;i<N;i++){
            int idx=k-b[i];
            if(idx>=0 && idx<=a[i]) inv[k]^=C[a[i]][idx];
        }
    }
    // Now find X,Y such that C(X,k-Y)=inv[k] for all k
    for(int X=0;X<300;X++) for(int Y=-200;Y<300;Y++){
        int ok=1;
        for(int k=0;k<605&&ok;k++){
            int idx=k-Y;
            int val=(idx>=0&&idx<=X)?C[X][idx]:0;
            if(val!=inv[k]) ok=0;
        }
        if(ok){printf("%d %d\n",X,Y);return 0;}
    }
}

#include <stdio.h>

int main() {
    int N;
    scanf("%d", &N);

    int x, y;
    long long sum_x = 0, sum_y = 0;
    int min_x = 1000000000, min_y = 1000000000;

    for (int i = 0; i < N; i++) {
        scanf("%d %d", &x, &y);
        sum_x += x;
        sum_y += y;
        if (x < min_x) min_x = x;
        if (y < min_y) min_y = y;
    }

    // The key: sum of coordinates of all on lamps mod 3 gives info,
    // and the original lamp (X,Y) is the unique point reachable.
    // Using the invariant: sum of x coordinates modulo N and sum of y coordinates gives direct formula.

    // For the known solution: X = (sum_x - min_x * N) / (N - 1)
    // Y = (sum_y - min_y * N) / (N - 1)

    long long X = (sum_x - (long long)min_x * N) / (N - 1);
    long long Y = (sum_y - (long long)min_y * N) / (N - 1);

    printf("%lld %lld\n", X, Y);

    return 0;
}

