typedef long long ll;

typedef struct {
    ll x, y;
} Point;

int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Point *p = (Point *)malloc(sizeof(Point) * N);
    ll *sx = (ll *)malloc(sizeof(ll) * N);
    ll *sy = (ll *)malloc(sizeof(ll) * N);
    ll *sd = (ll *)malloc(sizeof(ll) * N); /* x+y */

    for (int i = 0; i < N; i++) {
        scanf("%lld %lld", &p[i].x, &p[i].y);
        sx[i] = p[i].x;
        sy[i] = p[i].y;
        sd[i] = p[i].x + p[i].y;
    }

    qsort(sx, N, sizeof(ll), cmp_ll);
    qsort(sy, N, sizeof(ll), cmp_ll);
    qsort(sd, N, sizeof(ll), cmp_ll);

    ll X = 0, Y = 0;

    /* In XOR over F2, each operation toggles:
       x-parities: x twice, x+1 once  => contributes x+1
       y-parities: y twice, y+1 once  => contributes y+1
       (x+y)-parities: x+y twice, x+y+1 once => contributes x+y+1
       Therefore the parity-odd value among final on lamps gives:
       odd x = X, odd y = Y, odd (x+y) = X+Y.
    */

    for (int i = 0; i < N; ) {
        int j = i;
        while (j < N && sx[j] == sx[i]) j++;
        if (((j - i) & 1) != 0) {
            X = sx[i];
            break;
        }
        i = j;
    }

    for (int i = 0; i < N; ) {
        int j = i;
        while (j < N && sy[j] == sy[i]) j++;
        if (((j - i) & 1) != 0) {
            Y = sy[i];
            break;
        }
        i = j;
    }

    /* X and Y are uniquely determined; print them. */
    printf("%lld %lld\n", X, Y);

    free(p);
    free(sx);
    free(sy);
    free(sd);
    return 0;
}

