#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

// We use the invariant over F2.
// Let a lamp at (x,y) correspond to monomial X^x Y^y.
// One operation toggles
//   (x,y), (x,y+1), (x+1,y)
// i.e. adds X^x Y^y (1 + X + Y).
//
// Therefore the final configuration F satisfies
//   F = X^X0 Y^Y0 + (1 + X + Y) * G
// over F2.
// So modulo (1 + X + Y), F is exactly the initial monomial.
//
// In the quotient ring with relation Y = 1 + X, a monomial becomes
//   X^x (1 + X)^y.
// Over F2, by Lucas' theorem,
//   (1 + X)^y = sum_{k subset-of y} X^k,
// where coefficient of X^k is 1 iff k is a submask of y.
//
// Hence
//   F(X,1+X) = sum_i X^{xi} (1+X)^{yi}
// is a polynomial equal to a single monomial X^X0.
// So if we XOR contributions of all lamps to coefficients, exactly one degree remains.
//
// We represent y by its set submasks. Since yi <= 1e6 in typical constraints,
// O(sum 2^{popcount(yi)}) is feasible.
//
// Then X0 is the unique exponent with odd coefficient.
// Finally, using symmetry with X = 1 + Y, we similarly recover Y0.

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<pair<int,int>> p(N);
    int maxCoord = 0;
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        p[i] = {x, y};
        maxCoord = max(maxCoord, max(x, y));
    }

    // Enough size for exponent x + submask(y), similarly for y + submask(x)
    int LIM = 1;
    while (LIM <= 2 * maxCoord + 5) LIM <<= 1;

    vector<unsigned char> cx(LIM, 0), cy(LIM, 0);

    for (auto [x, y] : p) {
        // Add X^x (1+X)^y
        int s = y;
        while (true) {
            cx[x + s] ^= 1;
            if (s == 0) break;
            s = (s - 1) & y;
        }

        // Symmetrically add Y^y (1+Y)^x
        s = x;
        while (true) {
            cy[y + s] ^= 1;
            if (s == 0) break;
            s = (s - 1) & x;
        }
    }

    int X = -1, Y = -1;
    for (int i = 0; i < LIM; ++i) {
        if (cx[i]) {
            X = i;
            break;
        }
    }
    for (int i = 0; i < LIM; ++i) {
        if (cy[i]) {
            Y = i;
            break;
        }
    }

    cout << X << ' ' << Y << '\n';
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        Map<Long, int[]> points = new HashMap<>();
        for (int i = 0; i < N; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            long key = ((long) x << 32) | (y & 0xffffffffL);
            points.put(key, new int[]{x, y});
        }
        sc.close();

        // We need to find the unique (X,Y) such that starting from it,
        // using allowed toggles we get exactly the given set.
        // Inversion: process from high x+y to low, toggling when lamp is on.
        // Since coordinates can be negative, shift to positive range for sorting.

        List<int[]> list = new ArrayList<>(points.values());
        // Sort by (x+y) descending, then x descending
        list.sort((a, b) -> {
            int sumA = a[0] + a[1];
            int sumB = b[0] + b[1];
            if (sumA != sumB) return sumB - sumA;
            return b[0] - a[0];
        });

        Set<Long> onSet = new HashSet<>();
        for (int[] p : points.values()) {
            onSet.add(((long) p[0] << 32) | (p[1] & 0xffffffffL));
        }

        for (int[] p : list) {
            int x = p[0], y = p[1];
            long key = ((long) x << 32) | (y & 0xffffffffL);
            if (onSet.contains(key)) {
                // toggle (x,y), (x,y+1), (x+1,y)
                toggle(onSet, x, y);
                toggle(onSet, x, y + 1);
                toggle(onSet, x + 1, y);
            }
        }

        // After processing, only one lamp should remain
        if (onSet.size() != 1) {
            // Should not happen per problem constraints
            return;
        }
        long remaining = onSet.iterator().next();
        int rx = (int) (remaining >> 32);
        int ry = (int) (remaining & 0xffffffffL);
        System.out.println(rx + " " + ry);
    }

    static void toggle(Set<Long> set, int x, int y) {
        long key = ((long) x << 32) | (y & 0xffffffffL);
        if (set.contains(key)) {
            set.remove(key);
        } else {
            set.add(key);
        }
    }
}

